import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import MapTracker from '../components/MapTracker';
import './Checkout.css';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

function Checkout({ cartItems, cartTotal, user, token, onLogin, clearCart }) {
  const navigate = useNavigate();
  const [isLogin, setIsLogin] = useState(true);
  const [showLoginForm, setShowLoginForm] = useState(!user);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    password: '',
    address: '',
    notes: '',
    payment_method: 'cod'
  });
  const [deliveryLocation, setDeliveryLocation] = useState(null);
  const [deliveryInfo, setDeliveryInfo] = useState(null);
  const [deliveryError, setDeliveryError] = useState('');
  const [processing, setProcessing] = useState(false);
  const [orderSuccess, setOrderSuccess] = useState(null);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!user) {
      setShowLoginForm(true);
    }
  }, [user]);

  useEffect(() => {
    if (deliveryLocation) {
      calculateDelivery();
    }
  }, [deliveryLocation]);

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleAuth = async (e) => {
    e.preventDefault();
    setError('');

    try {
      const endpoint = isLogin ? '/api/auth/login' : '/api/auth/register';
      const payload = isLogin
        ? { email: formData.email, password: formData.password }
        : { name: formData.name, email: formData.email, phone: formData.phone, password: formData.password };

      const res = await axios.post(`${API_URL}${endpoint}`, payload);
      onLogin(res.data.user, res.data.token);
      setShowLoginForm(false);
    } catch (err) {
      setError(err.response?.data?.error || 'Authentication failed');
    }
  };

  const calculateDelivery = async () => {
    if (!deliveryLocation) return;
    setDeliveryError('');

    try {
      const res = await axios.post(`${API_URL}/api/orders/calculate-delivery`, {
        latitude: deliveryLocation.lat,
        longitude: deliveryLocation.lng
      });
      setDeliveryInfo(res.data);
      setDeliveryError('');
    } catch (err) {
      setDeliveryError(err.response?.data?.error || 'Delivery not available');
      setDeliveryInfo(null);
    }
  };

  const handleLocationChange = (lat, lng) => {
    setDeliveryLocation({ lat, lng });
  };

  const handlePlaceOrder = async () => {
    if (!user || !token) {
      setError('Please login to place an order');
      return;
    }

    if (!deliveryLocation) {
      setError('Please select a delivery location on the map');
      return;
    }

    if (!formData.address.trim()) {
      setError('Please enter your delivery address');
      return;
    }

    if (cartItems.length === 0) {
      setError('Your cart is empty');
      return;
    }

    setProcessing(true);
    setError('');

    try {
      const items = cartItems.map(item => ({
        product_id: item.product_id,
        quantity: item.quantity,
        price: item.price
      }));

      const res = await axios.post(
        `${API_URL}/api/orders/checkout`,
        {
          items,
          delivery_address: formData.address,
          latitude: deliveryLocation.lat,
          longitude: deliveryLocation.lng,
          payment_method: formData.payment_method,
          notes: formData.notes
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setOrderSuccess(res.data.order);
      clearCart();
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to place order');
    } finally {
      setProcessing(false);
    }
  };

  if (orderSuccess) {
    return (
      <div className="checkout-page">
        <div className="container">
          <div className="order-success">
            <div className="success-icon">✅</div>
            <h1>Order Placed Successfully!</h1>
            <p className="order-id">Order ID: <strong>{orderSuccess.order_id}</strong></p>
            <div className="success-details">
              <div className="success-detail">
                <span>📦 Status</span>
                <span className="badge badge-primary">{orderSuccess.order_status}</span>
              </div>
              <div className="success-detail">
                <span>💰 Total</span>
                <span>₹{orderSuccess.total}</span>
              </div>
              <div className="success-detail">
                <span>🚚 Delivery Fee</span>
                <span>₹{orderSuccess.delivery_fee}</span>
              </div>
              <div className="success-detail">
                <span>📍 Distance</span>
                <span>{orderSuccess.distance_km} km</span>
              </div>
              <div className="success-detail">
                <span>📅 Est. Delivery</span>
                <span>{new Date(orderSuccess.estimated_delivery).toLocaleDateString()}</span>
              </div>
              <div className="success-detail">
                <span>💳 Payment</span>
                <span>{orderSuccess.payment_method.toUpperCase()}</span>
              </div>
            </div>
            <p className="success-note">
              ⚠️ Orders are non-cancellable after confirmation.
            </p>
            <div className="success-actions">
              <button className="btn btn-primary" onClick={() => navigate('/dashboard')}>
                📋 View Orders
              </button>
              <button className="btn btn-outline" onClick={() => navigate('/')}>
                🏠 Back to Home
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="checkout-page">
      <div className="container">
        <h1 className="checkout-title">Checkout</h1>
        <p className="checkout-subtitle">Complete your order in a few simple steps</p>

        {error && <div className="alert alert-error">{error}</div>}

        <div className="checkout-grid">
          {/* Left Column - Login & Delivery Details */}
          <div className="checkout-left">
            {/* Auth Section */}
            {showLoginForm && (
              <div className="checkout-section card">
                <h2>{isLogin ? 'Login' : 'Create Account'}</h2>
                <p className="section-desc">
                  {isLogin ? 'Login to place your order' : 'Create an account to track your orders'}
                </p>
                <form onSubmit={handleAuth}>
                  {!isLogin && (
                    <div className="form-group">
                      <label>Full Name</label>
                      <input
                        type="text"
                        name="name"
                        value={formData.name}
                        onChange={handleInputChange}
                        required
                        placeholder="Your name"
                      />
                    </div>
                  )}
                  <div className="form-group">
                    <label>Email</label>
                    <input
                      type="email"
                      name="email"
                      value={formData.email}
                      onChange={handleInputChange}
                      required
                      placeholder="your@email.com"
                    />
                  </div>
                  {!isLogin && (
                    <div className="form-group">
                      <label>Phone Number</label>
                      <input
                        type="tel"
                        name="phone"
                        value={formData.phone}
                        onChange={handleInputChange}
                        required
                        placeholder="10 digit mobile number"
                      />
                    </div>
                  )}
                  <div className="form-group">
                    <label>Password</label>
                    <input
                      type="password"
                      name="password"
                      value={formData.password}
                      onChange={handleInputChange}
                      required
                      placeholder="Your password"
                    />
                  </div>
                  <button type="submit" className="btn btn-primary auth-submit">
                    {isLogin ? 'Login & Continue' : 'Register & Continue'}
                  </button>
                </form>
                <p className="auth-toggle">
                  {isLogin ? "Don't have an account? " : "Already have an account? "}
                  <button className="link-btn" onClick={() => setIsLogin(!isLogin)}>
                    {isLogin ? 'Register' : 'Login'}
                  </button>
                </p>
              </div>
            )}

            {/* User Info (when logged in) */}
            {user && !showLoginForm && (
              <div className="checkout-section card user-info-section">
                <div className="user-info-header">
                  <span className="user-avatar">👤</span>
                  <div>
                    <h3>{user.name}</h3>
                    <p>{user.email} | {user.phone}</p>
                  </div>
                </div>
                <button className="btn btn-outline" onClick={() => setShowLoginForm(true)}>
                  Switch Account
                </button>
              </div>
            )}

            {/* Delivery Address */}
            <div className="checkout-section card">
              <h2>📍 Delivery Details</h2>
              <div className="form-group">
                <label>Delivery Address</label>
                <textarea
                  name="address"
                  value={formData.address}
                  onChange={handleInputChange}
                  rows="3"
                  placeholder="Enter your full delivery address"
                  required
                ></textarea>
              </div>

              {user && (
                <>
                  <h2>🗺️ Select Delivery Location</h2>
                  <p className="section-desc">Click on the map to mark your delivery location</p>
                  <MapTracker onLocationChange={handleLocationChange} />
                  
                  {deliveryInfo && (
                    <div className="delivery-calculated">
                      <div className="delivery-info-row">
                        <span>📏 Distance</span>
                        <span><strong>{deliveryInfo.distance_km} km</strong></span>
                      </div>
                      <div className="delivery-info-row">
                        <span>🚚 Delivery Fee</span>
                        <span><strong>₹{deliveryInfo.delivery_fee}</strong></span>
                      </div>
                      <div className="delivery-info-row">
                        <span>💰 Min. Order</span>
                        <span><strong>₹{deliveryInfo.min_order_amount}</strong></span>
                      </div>
                    </div>
                  )}

                  {deliveryError && (
                    <div className="alert alert-error">{deliveryError}</div>
                  )}

                  <div className="form-group">
                    <label>Order Notes (Optional)</label>
                    <textarea
                      name="notes"
                      value={formData.notes}
                      onChange={handleInputChange}
                      rows="2"
                      placeholder="Any special instructions?"
                    ></textarea>
                  </div>
                </>
              )}
            </div>
          </div>

          {/* Right Column - Order Summary */}
          <div className="checkout-right">
            <div className="checkout-section card order-summary-card">
              <h2>🛒 Order Summary</h2>
              <div className="order-items">
                {cartItems.length === 0 ? (
                  <div className="empty-cart-msg">
                    <p>Your cart is empty</p>
                    <button className="btn btn-outline" onClick={() => navigate('/')}>
                      Browse Items
                    </button>
                  </div>
                ) : (
                  cartItems.map((item, index) => (
                    <div key={item.product_id || index} className="order-item">
                      <div className="order-item-info">
                        <span className="order-item-name">{item.name}</span>
                        <span className="order-item-qty">x{item.quantity}</span>
                      </div>
                      <span className="order-item-price">₹{item.price * item.quantity}</span>
                    </div>
                  ))
                )}
              </div>

              {cartItems.length > 0 && (
                <div className="order-totals">
                  <div className="order-total-row">
                    <span>Subtotal</span>
                    <span>₹{cartTotal}</span>
                  </div>
                  <div className="order-total-row">
                    <span>Delivery Fee</span>
                    <span>{deliveryInfo ? `₹${deliveryInfo.delivery_fee}` : '—'}</span>
                  </div>
                  <div className="order-total-row">
                    <span>Min. Order Required</span>
                    <span>{deliveryInfo ? `₹${deliveryInfo.min_order_amount}` : '—'}</span>
                  </div>
                  <div className="order-total-row order-total-final">
                    <span>Total</span>
                    <span>₹{deliveryInfo ? cartTotal + deliveryInfo.delivery_fee : cartTotal}</span>
                  </div>
                </div>
              )}

              {/* Payment Method */}
              <div className="payment-section">
                <h3>💳 Payment Method</h3>
                <div className="payment-options">
                  <label className={`payment-option ${formData.payment_method === 'cod' ? 'active' : ''}`}>
                    <input
                      type="radio"
                      name="payment_method"
                      value="cod"
                      checked={formData.payment_method === 'cod'}
                      onChange={handleInputChange}
                    />
                    <div className="payment-option-content">
                      <span className="payment-icon">💵</span>
                      <div>
                        <strong>Cash on Delivery</strong>
                        <small>Pay when you receive</small>
                      </div>
                    </div>
                  </label>
                  <label className={`payment-option ${formData.payment_method === 'upi' ? 'active' : ''}`}>
                    <input
                      type="radio"
                      name="payment_method"
                      value="upi"
                      checked={formData.payment_method === 'upi'}
                      onChange={handleInputChange}
                    />
                    <div className="payment-option-content">
                      <span className="payment-icon">📱</span>
                      <div>
                        <strong>UPI / Online</strong>
                        <small>Pay via Google Pay, PhonePe, etc.</small>
                      </div>
                    </div>
                  </label>
                </div>
              </div>

              {/* Place Order Button */}
              {user && cartItems.length > 0 && (
                <div className="place-order-section">
                  <div className="order-notes-warning">
                    ⚠️ Orders cannot be cancelled after confirmation
                  </div>
                  {deliveryInfo && cartTotal < deliveryInfo.min_order_amount && (
                    <div className="alert alert-error">
                      Minimum order amount for this distance is ₹{deliveryInfo.min_order_amount}.
                      Add ₹{deliveryInfo.min_order_amount - cartTotal} more to your cart.
                    </div>
                  )}
                  <button
                    className="btn btn-primary place-order-btn"
                    onClick={handlePlaceOrder}
                    disabled={processing || (deliveryInfo && cartTotal < deliveryInfo.min_order_amount)}
                  >
                    {processing ? '⏳ Processing...' : '🚀 Place Order'}
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Checkout;
